const offerings={sake:0,dango:0,keyReady:false,models:{},altar:{x:-90.8,z:-23},truck:{x:74,z:-17}}; // 0=not collected, 1=carried, 2=offered
function offeringModel(name,x,y,z){const g=world.assets.templates.get('offering_'+name).clone(true);g.position.set(x,y,z);g.name='quest-'+name;scene.add(g);return g;}
const offeringBuild=MapManager.prototype.build;
MapManager.prototype.build=function(){
 offeringBuild.call(this);
 const t=offerings.truck,clear=(x,z)=>Math.hypot(x-t.x,z-t.z)<5;
 const kept=obstacles.filter(o=>!clear(o.x,o.z));obstacles.length=0;buckets.clear();for(const o of kept)addObstacle(o.x,o.z,o.r,o.kind);
 if(naturalForest){naturalForest.positions=naturalForest.positions.filter(p=>!clear(p.x,p.z));naturalForest.update(true);}
 this.assets.place('offering_truck',t.x,t.z,{distance:95});
 for(const z of [-1.5,-.5,.5,1.5])addObstacle(t.x,t.z+z,1.08,'truck');
 navReady=false;buildNav();
};
const offeringInit=init;init=async function(){await offeringInit();if(!ready)return;
 offerings.models.sake=offeringModel('sake',offerings.truck.x+.68,.86,offerings.truck.z-1);
 offerings.models.dango=offeringModel('dango',0,world.map.floor(0,-82)+.025,-82);
 const tag=document.createElement('div');tag.id='offering-status';tag.className='status-caption';tag.style.marginTop='7px';$('key-status').after(tag);
};
function resetOfferings(){
 offerings.sake=offerings.dango=0;offerings.keyReady=false;
 const s=offerings.models.sake,d=offerings.models.dango;
 if(s&&d){s.position.set(offerings.truck.x+.68,.86,offerings.truck.z-1);d.position.set(0,world.map.floor(0,-82)+.025,-82);s.visible=d.visible=true;}
 const k=seven.lock.key;k.x=offerings.altar.x;k.z=offerings.altar.z;k.group.position.set(k.x,world.map.floor(k.x,k.z)+.35,k.z);k.group.visible=false;k.found=false;
 updateHUD();
}
const offeringStart=GameManager.prototype.start;GameManager.prototype.start=function(){offeringStart.call(this);resetOfferings();};
function offeringHit(){
 if(state!=='playing')return null;
 if(offerings.sake===0&&Math.hypot(player.x-(offerings.truck.x+1.8),player.z-(offerings.truck.z-1))<1.9)return {type:'offering-pickup',item:'sake'};
 if(offerings.dango===0&&Math.hypot(player.x,player.z+82)<2.2&&clearLine(player.x,player.z,0,-82))return {type:'offering-pickup',item:'dango'};
 const a=offerings.altar;
 if(Math.hypot(player.x-a.x,player.z-a.z)<2.2&&clearLine(player.x,player.z,a.x,a.z)){
  if(offerings.keyReady&&!seven.lock.found)return {type:'gate-key'};
  if(offerings.sake<2||offerings.dango<2)return {type:'offering-altar',item:offerings.sake===1?'sake':offerings.dango===1?'dango':null};
 }
 return null;
}
const offeringInteraction=getInteraction;getInteraction=function(){const h=offeringHit();if(h?.type==='offering-altar'&&!h.item)return offeringInteraction()||h;return h||offeringInteraction();};
const offeringTake=TunnelLock.prototype.take;TunnelLock.prototype.take=function(){if(!offerings.keyReady||this.found)return;offeringTake.call(this);};
const offeringInteract=interact;interact=function(){
 const h=offeringHit();if(h?.type==='offering-pickup'){
  offerings[h.item]=1;offerings.models[h.item].visible=false;audio.pickup();toast((h.item==='sake'?'お酒':'団子')+'を手に入れた。洞窟の仏像に供えられそうだ。',4);updateHUD();return;
 }
 if(h?.type==='offering-altar'){
  if(!h.item){toast('仏像の前に、お供えできそうな場所がある。',4);return;}
  offerings[h.item]=2;const m=offerings.models[h.item],a=offerings.altar;m.position.set(a.x-.65,world.map.floor(a.x,a.z)+.03,a.z+(h.item==='sake'?-.65:.65));m.visible=true;audio.pickup();
  if(offerings.sake===2&&offerings.dango===2){offerings.keyReady=true;seven.lock.key.group.visible=true;toast('二つの供物を供えると、仏像の前に封鎖の鍵が現れた。',5);}else toast((h.item==='sake'?'お酒':'団子')+'を供えた。もう一つの供物が必要だ。',4);
  updateHUD();return;
 }
 if(h?.type==='gate-key'){seven.lock.take();return;}
 offeringInteract();
};
const offeringPlayer=updatePlayer;updatePlayer=function(dt){offeringPlayer(dt);const h=offeringHit();if(h){show('interaction');$('interaction').disabled=false;$('interaction').textContent=h.type==='gate-key'?'封鎖の鍵を拾う':h.type==='offering-pickup'?(h.item==='sake'?'荷台のお酒を拾う':'団子を拾う'):h.item?(h.item==='sake'?'お酒を供える':'団子を供える'):'仏像の供え場所を調べる';}};
const offeringHUD=updateHUD;updateHUD=function(){offeringHUD();const label=n=>['未取得','所持','供え済み'][n];if($('offering-status'))$('offering-status').textContent='酒：'+label(offerings.sake)+' ／ 団子：'+label(offerings.dango);if(!seven?.lock.found)$('mission-hint').textContent+=offerings.keyReady?' · 仏像の前の鍵を拾う':' · 酒と団子を洞窟の仏像に供える';};
